uniform float2 resolution;
uniform float phase;

half4 main(float2 point) {
  float2 uv = point / resolution;
  float sweep = smoothstep(0.24, 0.0, abs((uv.x + uv.y * 0.18) - (phase * 1.18 + 0.02)));
  float edge = smoothstep(0.62, 0.08, distance(uv, float2(0.5, 0.5)));
  float3 spectral = 0.5 + 0.5 * cos(6.28318 * (float3(uv.x * 1.15 + phase * 0.08) + float3(0.0, 0.34, 0.67)));
  float3 base = float3(0.82, 0.97, 1.0);
  float3 color = mix(base, spectral, 0.14 + sweep * 0.42);
  color += sweep * 0.23 + edge * 0.05;
  return half4(half3(clamp(color, 0.0, 1.0)), 1.0);
}
